// 1. Zmienna lokalna z inicjalizatorem
var imie = "Kasia";               // String
var wiek = 27;                    // int
var lista = new ArrayList<String>(); // ArrayList<String>

// 2. Zmienna w for-each
for (var jezyk : lista) { ... }   // jezyk: String

// 3. try-with-resources
try (var reader = new BufferedReader(new StringReader("..."))) { ... }

// 4. Zwykla petla for
for (var i = 0; i < 3; i++) { ... } // i: int

var dziala dla: zmiennych lokalnych z inicjalizatorem, zmiennych for-each, zasobow try-with-resources, licznikow zwyklego for.

exercises.solution:
var imie = "Nowak";
System.out.println(imie);
System.out.println(imie.getClass().getSimpleName());

var liczba = 42;      // int
var pi = 3.14;        // double
var flaga = true;     // boolean
var litera = 'A';     // char
System.out.println(liczba + " (int)");
System.out.println(pi + " (double)");
System.out.println(flaga + " (boolean)");
System.out.println(litera + " (char)");

int[] liczby = {2, 4, 6, 8, 10};
int sum = 0;
for (var x : liczby) {
    sum += x;
}
System.out.println(sum); // 30

for (var i = 1; i <= 5; i++) {
    System.out.println(i);
}

try (var reader = new BufferedReader(new StringReader("wiersz1\nwiersz2\nwiersz3"))) {
    String linia;
    while ((linia = reader.readLine()) != null) {
        System.out.println(linia);
    }
} catch (java.io.IOException e) {
    e.printStackTrace();
}

var lista = new ArrayList<Integer>();
lista.add(10);
lista.add(20);
lista.add(30);
int sum = 0;
for (var x : lista) {
    sum += x;
}
System.out.println(sum); // 60

// 1. class Foo { var pole = 10; } - zabronione, bo pole klasy jest CZESCIA publicznego
//    kontraktu klasy i musi miec jawny, czytelny typ w API.
// 2. void metoda(var x) { } - zabronione, bo sygnatura metody musi byc jednoznaczna
//    dla kazdego wywolujacego kod, bez potrzeby wnioskowania.
// 3. var metoda() { return 5; } - zabronione z tego samego powodu co (2) - typ zwracany
//    jest czescia kontraktu API metody, widocznego dla kazdego wywolujacego.

var mapa = new HashMap<String, Integer>();
mapa.put("jablko", 3);
mapa.put("banan", 2);
mapa.put("gruszka", 4);
for (var entry : mapa.entrySet()) {
    System.out.println(entry.getKey() + ": " + entry.getValue());
}

// var x; - blad kompilacji: "cannot infer type for local variable x"
// var wnioskuje typ WYLACZNIE na podstawie wyrazenia PO PRAWEJ STRONIE przypisania (=).
// Bez inicjalizatora nie ma ZADNEGO zrodla informacji, z ktorego kompilator moglby
// wywnioskowac typ - w odroznieniu od jawnego typu (np. 'int x;'), gdzie typ jest podany
// wprost, var CALKOWICIE polega na tym, co stoi po prawej stronie.

// var y = null; - blad kompilacji, bo sam literal 'null' nie niesie zadnej informacji o TYPIE
// (moglby byc null'em dla String, Integer, dowolnej klasy - kompilator nie ma jak wybrac).
// var y = (String) null; DZIALA, bo jawne rzutowanie (String) DOSTARCZA typ - teraz kompilator
// wie, ze y jest typu String (wartosc null).
var tekst = (String) null;
System.out.println(tekst == null); // true

var tekst = "abc";
// tekst = 42; // BLAD: incompatible types: int cannot be converted to String
// Typ zmiennej 'tekst' zostal USTALONY RAZ, w czasie kompilacji (na podstawie inicjalizatora
// "abc"), jako String. Od tego momentu zmienna zachowuje sie DOKLADNIE jak jawnie zadeklarowana
// 'String tekst' - proba przypisania wartosci int jest bledem kompilacji, tak samo jak przy
// zwyklym typowaniu.

var listaObiektow = new ArrayList<>();
// Wywnioskowany typ to ArrayList<Object> - diamond <> sam z siebie nie zawiera typu, a var
// (w odroznieniu od jawnego 'List<String> l = new ArrayList<>();') nie dostarcza ZADNEGO
// kontekstu, z ktorego kompilator moglby wziac typ elementow - domyslnie ladujemy do Object.
listaObiektow.add("tekst");
listaObiektow.add(42);
System.out.println(listaObiektow); // [tekst, 42] - oba dodane bez bledu kompilacji

List<String> l1 = new ArrayList<>();
var l2 = new ArrayList<String>();
// l1 ma statyczny (deklarowany) typ List<String> - INTERFEJS. Mozna by pozniej podmienic
// implementacje (np. new LinkedList<>()) bez zmiany typu zmiennej.
// l2 ma statyczny typ ArrayList<String> - KONKRETNA KLASA (bo var wnioskuje typ Z TEGO, co
// stoi po prawej stronie, a tam jest jawnie ArrayList). Roznica ma znaczenie np. gdy pozniej
// chcemy wywolac metode specyficzna DLA ArrayList (np. ensureCapacity) - dziala tylko na l2,
// nie na l1, mimo ze OBA obiekty w runtime to faktycznie ArrayList.

static Map<String, List<Integer>> pogrupuj() {
    Map<String, List<Integer>> mapa = new HashMap<>();
    mapa.put("parzyste", List.of(2, 4, 6));
    mapa.put("nieparzyste", List.of(1, 3, 5));
    return mapa;
}

var wynik = pogrupuj();
System.out.println(wynik);
// var ZDECYDOWANIE poprawia tu czytelnosc - typ Map<String, List<Integer>> jest dlugi i
// powtorzenie go po obu stronach przypisania nie dodaje zadnej wartosci ponad to, co juz
// mowi nazwa metody 'pogrupuj()'.

var wynik = 5 / 2.0;
System.out.println(wynik); // 2.5
// Wywnioskowany typ to double - reguly promocji typow w wyrazeniach arytmetycznych mowia,
// ze gdy jeden z operandow operatora binarnego jest double (tu: 2.0), CALE wyrazenie jest
// promowane do double (int '5' jest niejawnie rozszerzany), niezaleznie od tego, ze var
// bylby uzyty.

record Osoba(String imie, int wiek) {}

var osoba = new Osoba("Kasia", 25);
System.out.println(osoba); // Osoba[imie=Kasia, wiek=25]
// var wywnioskowal DOKLADNIE typ 'Osoba' (nie np. Object czy Record) - potwierdza to fakt,
// ze osoba.imie() i osoba.wiek() (akcesory wygenerowane przez rekord) sa dostepne bezposrednio
// bez zadnego rzutowania.

var tablica = new int[]{1, 2, 3, 4, 5};
System.out.println("Dlugosc: " + tablica.length);
for (var i = 0; i < tablica.length; i++) {
    System.out.println(tablica[i]);
}

static Object policzRabat(double cena, double procent) {
    return cena * (1 - procent / 100);
}

var wynik = policzRabat(100, 10);
System.out.println(wynik);
// Lepsza wersja: static double policzRabat(double cena, double procent) { ... }
// oraz double wynik = policzRabat(100, 10); - typ zwracany Object CALKOWICIE ukrywa, ze
// metoda faktycznie zwraca liczbe, a var przy takim wywolaniu jeszcze POGARSZA czytelnosc,
// bo nawet zajrzenie do sygnatury metody nie ujawnia prawdziwego typu.

try (var r1 = new BufferedReader(new StringReader("a\nb"));
     var r2 = new BufferedReader(new StringReader("x\ny"))) {
    String line;
    while ((line = r1.readLine()) != null) System.out.println("r1: " + line);
    while ((line = r2.readLine()) != null) System.out.println("r2: " + line);
} catch (java.io.IOException e) {
    e.printStackTrace();
}

// WARTO uzyc var:
// 1. var lista = new ArrayList<String>(); - typ w samej nazwie klasy po prawej.
// 2. var uzytkownik = new User("Ala", 30); - konstruktor mowi wprost.
// 3. var licznikBledow = 0; - nazwa zmiennej jest bardzo opisowa.
// 4. var wynikStreamu = lista.stream().filter(...).toList(); - dlugi typ generyczny, oczywisty z kontekstu.
// 5. var i = 0; jako licznik petli for - konwencja powszechnie zrozumiala.
//
// NALEZY unikac var:
// 1. var wynik = obliczSuma(); - typ zwracany metody nieoczywisty bez zajrzenia do jej ciala.
// 2. var dane = pobierzDane(); - calkowicie nieczytelne (List? Map? Optional?).
// 3. var l = new ArrayList<String>(); gdy chcemy podkreslic programowanie do interfejsu List.
// 4. var x = metoda(); gdy 'metoda' zwraca Object lub bardzo ogolny typ.
// 5. var wynik = a ? b : c; gdy typy b i c nie sa oczywiste na pierwszy rzut oka.

static void jawnyTyp() {
    ArrayList<String> lista = new ArrayList<>();
    lista.add("a");
    lista.add("b");
    System.out.println(lista);
}

static void zVar() {
    var lista = new ArrayList<String>();
    lista.add("a");
    lista.add("b");
    System.out.println(lista);
}
// var jest CZYSTO cecha kompilatora (javac) - podczas kompilacji kompilator wnioskuje
// konkretny typ i generuje DOKLADNIE taki sam bajtkod, jakby ten typ byl podany jawnie.
// W pliku .class nie ma zadnego sladu 'var' - to dlatego zachowanie w runtime, wydajnosc
// i introspekcja (getClass()) sa identyczne w obu wersjach.

static <T extends Number> double podwojna(T liczba) {
    return liczba.doubleValue() * 2;
}

var wynik = podwojna(21);
System.out.println(wynik); // 42.0
// var wywnioskowal typ 'double' - bo sygnatura metody deklaruje TYP ZWRACANY jako double
// (nie T), niezaleznie od tego, ze argument byl typu Integer. var patrzy na DEKLAROWANY
// typ wyrazenia po prawej, nie na typ argumentow przekazanych do metody.

static <T> List<T> wrapInList(T value) {
    return List.of(value);
}

var wynik = wrapInList(42);
System.out.println(wynik);
System.out.println(wynik.get(0).getClass().getSimpleName()); // Integer

var wynik = List.of(1, 2, 3, 4, 5).stream()
    .filter(x -> x % 2 == 0)
    .map(x -> x * 10)
    .toList();
System.out.println(wynik); // [20, 40]
// var jest tu w pelni uzasadniony - typ koncowy to prosty List<Integer>, a caly lancuch
// metod JASNO pokazuje, ze wynikiem jest lista liczb. Jawny typ 'List<Integer> wynik = ...'
// nie dodalby zadnej wartosci informacyjnej ponad to, co juz widac z .toList() na koncu.

java.util.function.BinaryOperator<Integer> dodaj = (var a, var b) -> a + b;
System.out.println(dodaj.apply(3, 4)); // 7
// Kompiluje sie poprawnie - var w parametrach lambdy zostal wprowadzony w Javie 11 (JEP 323),
// wiec dziala na tym projekcie (Java 21). WAZNE ograniczenie (nie testowane tu): jesli uzyjesz
// var dla JEDNEGO parametru lambdy, MUSISZ uzyc go dla WSZYSTKICH parametrow tej samej lambdy -
// nie mozna mieszac (var a, b) -> ... ani (var a, int b) -> ...

static List<String> stworz() {
    return new ArrayList<>();
}

var wynik = stworz();
// var wywnioskowal typ List<String> - DOKLADNIE taki, jaki DEKLARUJE sygnatura metody stworz().
// Mimo ze w runtime obiekt jest FAKTYCZNIE instancja ArrayList, var 'widzi' tylko STATYCZNY,
// deklarowany typ zwracany metody - nie ma dostepu do informacji o konkretnej implementacji.
System.out.println(wynik.getClass().getSimpleName()); // ArrayList - ale statyczny typ to List

// Jawny typ (bardzo dlugi, powtorzony DWA razy):
// Map<String, List<Map<String, Integer>>> dane = new HashMap<String, List<Map<String, Integer>>>();
//
// Z var (typ podany TYLKO RAZ, po prawej):
// var dane = new HashMap<String, List<Map<String, Integer>>>();
//
// Wersja z var jest ZDECYDOWANIE czytelniejsza - unika powtorzenia OGROMNEGO typu
// generycznego dwukrotnie. Zasada 'typ widoczny z prawej strony' jest tu spelniona,
// bo konstruktor 'new HashMap<...>()' JAWNIE pokazuje pelny typ generyczny - var
// nic nie ukrywa, tylko eliminuje zbedne powtorzenie.

// Java var: wnioskowanie typu zmiennej LOKALNEJ w czasie kompilacji, typ ustalony RAZ.
// C++ auto: bardzo podobny mechanizm - kompilator wnioskuje typ zmiennej z inicjalizatora,
// rowniez WYLACZNIE w czasie kompilacji (statyczne typowanie).
// Kotlin val/var: val to STALA (niemutowalna referencja) z wywnioskowanym typem, var to
// mutowalna zmienna z wywnioskowanym typem - ale w OBU przypadkach typ jest ustalany RAZ,
// statycznie, przy kompilacji - Kotlin var NIE pozwala zmienic TYPU zmiennej w trakcie dzialania.
// Zadien z tych trzech mechanizmow NIE jest dynamicznym typowaniem jak w Pythonie/JavaScripcie -
// Java var NIGDY nie pozwala, by ta sama zmienna przechowywala rozne typy w trakcie dzialania programu.

static void opisz(Object o) {
    System.out.println(o.getClass().getName());
}

var zVar = "test";
String jawna = "test";
opisz(zVar);
opisz(jawna);
// Oba wywolania wypisza DOKLADNIE to samo: java.lang.String - potwierdza to, ze var
// nie zmienia NICZEGO w runtime, tylko jest 'znika' po kompilacji, zastapiony jawnym typem.

static double sredniaCena(Map<String, Double> rejestr) {
    return rejestr.values().stream().mapToDouble(Double::doubleValue).average().orElse(0);
}

var rejestr = new HashMap<String, Double>();
rejestr.put("Laptop", 3500.0);
rejestr.put("Mysz", 50.0);
rejestr.put("Klawiatura", 150.0);
rejestr.put("Monitor", 800.0);

double srednia = sredniaCena(rejestr);
System.out.println("Srednia cena: " + srednia);
// var przy 'rejestr' poprawia czytelnosc - typ HashMap<String, Double> jest jawnie widoczny
// w konstruktorze po prawej, wiec powtorzenie go po lewej byloby zbedne. Jawny 'double' przy
// wyniku sredniaCena(...) jest CELOWY, mimo ze typ 'double' jest prosty - bo WARTOSC srednia
// nie jest oczywista bez zajrzenia do ciala metody, a jawny typ przynajmniej gwarantuje
// jednoznacznosc na poziomie liczby (a nie np. Object jak w Zadaniu 18).
